package deposit.common;

import deposit.service.query.*;
import deposit.repository.GetQueryRepository.Binding;
import java.util.*;
import java.util.stream.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class QueryTest {
    static QueryTranslator.QueryPlan plan(String query,Map<String,Object> parameters){return QueryTranslator.translateToCypher(QueryParser.parse(query),"namespace",3,name->new QueryTranslator.ClassInfo(name,Map.of("Mass","Float","Code","String","N","Integer","Elapsed","Duration","Bag","DDict")),parameters,()->{});}
    static List<QueryExecution.Row> run(String query,List<Object> values){var p=plan(query,Map.of());var bindings=new ArrayList<Binding>();int i=0;for(Object v:values){var fields=new HashMap<QueryTranslator.Field,QueryValues.Cell>();for(var f:p.fields)fields.put(f,new QueryValues.Cell(f.type(),v,true));bindings.add(new Binding(Map.of(),fields,Map.of(),List.of("id"+i++)));}try(var rows=new QueryExecution(p,()->{}).execute(bindings.stream())){return rows.toList();}}
    @Test void precedenceAndEscapedTokens(){var p=QueryParser.parse("SELECT \"A\"\"B\".Code AS code WHERE code = 'it''s' OR code = 'x' AND NOT code IS MISSING");assertEquals("A\"B",p.select().getFirst().ref().object());var root=(QueryParser.Logic)p.where();assertEquals("OR",root.op());assertEquals("AND",((QueryParser.Logic)root.right()).op());}
    @Test void rejectsIncompleteOrUnsupportedGrammar(){assertThrows(ExceptionHandler.DepositException.class,()->QueryParser.parse("SELECT A WHERE "+"NOT ".repeat(200)+"A.N=1"));for(String q:List.of("SELECT A trailing","SELECT A WHERE A-*->B","SELECT A WHERE A-*0..2->B","SELECT A WHERE A-*1..11->B","SELECT SUM(A.N)","SELECT A WHERE A.N IN (1,2)","SELECT A WHERE A.N = 1e999","SELECT A WHERE A.N = 'unterminated"))assertThrows(ExceptionHandler.DepositException.class,()->QueryParser.parse(q),q);}
    @Test void typedParametersAndInjectionAreBound(){String dangerous="x') MATCH (n) DETACH DELETE n //";var p=plan("SELECT A.Code WHERE A.Code = $value",Map.of("value",dangerous));assertFalse(p.cypher.contains(dangerous));assertTrue(p.cypher.startsWith("CYPHER 25"));assertThrows(ExceptionHandler.DepositException.class,()->plan("SELECT A.Code WHERE A.Code=$v AND A.N=$v",Map.of("v","x")));assertThrows(ExceptionHandler.DepositException.class,()->plan("SELECT A.Code",Map.of("unused",1L)));}
    @Test void scopeAndConnectivity(){var p=plan("SELECT A.Code WHERE A-r->B AND A-s->B",Map.of());System.out.println("Query generated Cypher: "+p.cypher+" parameters="+p.parameters);assertEquals(1,p.bindings.size());assertEquals(2,p.relations.size());assertThrows(ExceptionHandler.DepositException.class,()->plan("SELECT A,B WHERE A-r->B OR A.Code='x'",Map.of()));assertEquals(2,plan("SELECT A AS a, A AS b WHERE a-r->b",Map.of()).bindings.size());}
    @Test void collectIsStandaloneAndTypePreserving(){var p=plan("SELECT COLLECT(A.Bag) AS value",Map.of());assertTrue(p.collect);assertFalse(p.aggregate);assertEquals("DDict",p.columns().getFirst().get("type"));assertThrows(ExceptionHandler.DepositException.class,()->plan("SELECT COLLECT(A.N) AS n,A",Map.of()));assertThrows(ExceptionHandler.DepositException.class,()->plan("SELECT COLLECT(A) AS n",Map.of()));assertEquals(2,run("SELECT COLLECT(A.N) AS n",Arrays.asList(1L,null,1L)).size());assertEquals(1,run("SELECT COLLECT(DISTINCT A.N) AS n",Arrays.asList(1L,null,1L)).size());}
    @Test void aggregateTypesAndFixedNumbers(){var values=List.<Object>of(10.0,20.0);assertEquals(30.0,run("SELECT SUM(A.Mass) AS n",values).getFirst().cells().getFirst().value());assertEquals(12.5,run("SELECT PERCENTILE(A.Mass,0.25) AS n",values).getFirst().cells().getFirst().value());assertEquals(Math.sqrt(50),((Number)run("SELECT STDEV(A.Mass) AS n",values).getFirst().cells().getFirst().value()).doubleValue(),1e-12);assertEquals("Float",plan("SELECT AVG(A.N) AS n",Map.of()).columns().getFirst().get("type"));}
    @Test void emptyAggregatesAndOverflow(){assertEquals(0L,run("SELECT SUM(A.N) AS n",List.of()).getFirst().cells().getFirst().value());assertNull(run("SELECT AVG(A.N) AS n",List.of()).getFirst().cells().getFirst().value());assertTrue(run("SELECT COLLECT(A.N) AS n",List.of()).isEmpty());assertThrows(ExceptionHandler.DepositException.class,()->run("SELECT SUM(A.N) AS n",List.of(Long.MAX_VALUE,1L)));assertThrows(ExceptionHandler.DepositException.class,()->run("SELECT SUM(A.Mass) AS n",List.of(Double.MAX_VALUE,Double.MAX_VALUE)));}
    @Test void presenceAndStructuralEquality(){assertNotEquals(QueryValues.key(new QueryValues.Cell("Float",null,false)),QueryValues.key(new QueryValues.Cell("Float",null,true)));assertTrue(QueryValues.equal("DDict",Json.map("a",1L,"b",2L),Json.map("b",2L,"a",1L)));}
    @Test void durationAndStructuredOrdering(){var month=Json.map("months",1L,"days",0L,"seconds",0L,"nanoseconds",0L);var days=Json.map("months",0L,"days",30L,"seconds",0L,"nanoseconds",0L);assertTrue(QueryValues.compare("Duration",month,days)>0);assertThrows(ExceptionHandler.DepositException.class,()->plan("SELECT A.Bag ORDER BY A.Bag",Map.of()));assertThrows(ExceptionHandler.DepositException.class,()->plan("SELECT MIN(A.Bag) AS x",Map.of()));}
    @Test void mixedSortDirectionsNullLastAndThreeValuedPredicates(){var rows=run("SELECT A.Mass AS mass ORDER BY mass DESC",Arrays.asList(10.0,null,20.0));assertEquals(20.0,rows.getFirst().cells().getFirst().value());assertNull(rows.getLast().cells().getFirst().value());assertEquals(2,run("SELECT A.Mass WHERE A.Mass=10 OR A.Mass=20",Arrays.asList(10.0,null,20.0)).size());assertEquals(1,run("SELECT A.Mass WHERE NOT A.Mass=10",Arrays.asList(10.0,null,20.0)).size());assertEquals(1,run("SELECT A.Mass WHERE A.Mass IN [10,NULL]",Arrays.asList(10.0,null,20.0)).size());}
}
